  groupExit_leaveBodyAlone: 'ਤੁਹਾਡਾ ਬੈਲੇਂਸ ਬਰਾਬਰ ਹੈ। ਗਰੁੱਪ ਵਿੱਚ ਹੋਰ ਕੋਈ ਸ਼ਾਮਲ ਨਹੀਂ ਹੋਇਆ, ਇਸ ਲਈ ਇਹ ਹਮੇਸ਼ਾ ਲਈ ਮਿਟਾ ਦਿੱਤਾ ਜਾਵੇਗਾ।',
