  profile_signOutTitle: 'ਸਾਈਨ ਆਊਟ ਕਰਨਾ ਹੈ?',
  profile_signOutBody: 'ਸਭ ਕੁਝ ਤੁਹਾਡੇ {provider} ਅਕਾਊਂਟ ਨਾਲ ਸਿੰਕ ਹੈ। ਜਦੋਂ ਤੁਸੀਂ ਸਾਈਨ ਆਊਟ ਕਰਦੇ ਹੋ, ਅਸੀਂ ਇਸ ਬ੍ਰਾਊਜ਼ਰ ਵਿਚਲੀ ਕਾਪੀ ਮਿਟਾ ਦਿੰਦੇ ਹਾਂ। ਦੁਬਾਰਾ ਸਾਈਨ ਇਨ ਕਰਨ ’ਤੇ ਤੁਹਾਡੇ ਗਰੁੱਪ ਵਾਪਸ ਆ ਜਾਂਦੇ ਹਨ।',
  profile_signOutPendingTitleOne: '{count} ਬਦਲਾਅ ਹਾਲੇ ਅੱਪਲੋਡ ਨਹੀਂ ਹੋਇਆ',
  profile_signOutPendingTitleOther: '{count} ਬਦਲਾਅ ਹਾਲੇ ਅੱਪਲੋਡ ਨਹੀਂ ਹੋਏ',
  profile_signOutPendingBody: 'ਸਿੰਕ ਪੂਰਾ ਹੋਣ ਤੱਕ ਤੁਹਾਡਾ ਡਾਟਾ ਇਸ ਬ੍ਰਾਊਜ਼ਰ ਵਿੱਚ ਰਹਿੰਦਾ ਹੈ। ਸਭ ਕੁਝ ਅੱਪਲੋਡ ਹੁੰਦੇ ਹੀ, ਅਸੀਂ ਸਾਈਨ ਆਊਟ ਕਰਕੇ ਲੋਕਲ ਕਾਪੀ ਮਿਟਾ ਦਿੰਦੇ ਹਾਂ।',
  profile_signOutPendingBodyOffline: 'ਤੁਸੀਂ ਆਫ਼ਲਾਈਨ ਹੋ। ਸਿੰਕ ਪੂਰਾ ਹੋਣ ਤੱਕ ਤੁਹਾਡਾ ਡਾਟਾ ਇਸ ਬ੍ਰਾਊਜ਼ਰ ਵਿੱਚ ਰਹਿੰਦਾ ਹੈ। ਸਭ ਕੁਝ ਅੱਪਲੋਡ ਹੁੰਦੇ ਹੀ, ਅਸੀਂ ਸਾਈਨ ਆਊਟ ਕਰਕੇ ਲੋਕਲ ਕਾਪੀ ਮਿਟਾ ਦਿੰਦੇ ਹਾਂ।',
