  profile_eraseTitle: 'ਇਸ ਬ੍ਰਾਊਜ਼ਰ ਤੋਂ ਪ੍ਰੋਫਾਈਲ ਮਿਟਾਉਣਾ ਹੈ?',
  profile_eraseBody: 'ਤੁਹਾਡੇ ਅਕਾਊਂਟ ਵਿੱਚ Google ਜਾਂ Apple ਸਾਈਨ ਇਨ ਨਹੀਂ ਹੈ। ਜਦੋਂ ਤੁਸੀਂ ਸਾਈਨ ਆਊਟ ਕਰਦੇ ਹੋ, ਅਸੀਂ ਇਸ ਬ੍ਰਾਊਜ਼ਰ ਦੀ ਕਾਪੀ ਮਿਟਾ ਦਿੰਦੇ ਹਾਂ। ਵਾਪਸ ਆਉਣ ਲਈ, ਤੁਹਾਨੂੰ ਰਿਕਵਰੀ ਕੋਡ ਚਾਹੀਦਾ ਹੈ। 30 ਦਿਨ ਨਾ ਵਰਤਣ ਤੋਂ ਬਾਅਦ, ਅਕਾਊਂਟ ਮਿਟਾ ਦਿੱਤਾ ਜਾਂਦਾ ਹੈ ਅਤੇ ਕੋਡ ਕੰਮ ਕਰਨਾ ਬੰਦ ਕਰ ਦਿੰਦਾ ਹੈ।',
  profile_eraseBodyNoCode: 'ਤੁਸੀਂ ਇਸਨੂੰ ਬਿਨਾਂ ਅਕਾਊਂਟ ਦੇ ਵਰਤਦੇ ਹੋ ਅਤੇ ਹਾਲੇ ਸਿੰਕ ਨਹੀਂ ਕੀਤਾ, ਇਸ ਲਈ ਕੋਈ ਰਿਕਵਰੀ ਕੋਡ ਨਹੀਂ ਹੈ। ਜਦੋਂ ਤੁਸੀਂ ਛੱਡਦੇ ਹੋ, ਤੁਹਾਡਾ ਪ੍ਰੋਫਾਈਲ ਹਮੇਸ਼ਾ ਲਈ ਚਲਾ ਜਾਂਦਾ ਹੈ।',
