  home_recoveryBody: 'ਤੁਸੀਂ ਇਸ ਨੂੰ ਅਕਾਊਂਟ ਤੋਂ ਬਿਨਾਂ ਵਰਤ ਰਹੇ ਹੋ। ਜੇ ਤੁਸੀਂ ਇਹ ਬ੍ਰਾਊਜ਼ਰ ਸਾਫ਼ ਕਰ ਦਿੰਦੇ ਹੋ, ਤਾਂ ਇਹੀ ਕੋਡ ਤੁਹਾਡੇ ਗਰੁੱਪ ਵਾਪਸ ਲਿਆਉਂਦਾ ਹੈ।',
