  home_notificationsBody: 'ਜਦੋਂ ਕੋਈ ਤੁਹਾਡੇ ਨਾਲ ਖਰਚਾ ਜੋੜੇ ਜਾਂ ਤੁਹਾਨੂੰ ਭੁਗਤਾਨ ਮਾਰਕ ਕਰੇ, ਤਾਂ ਸੂਚਨਾ ਪਾਓ।',
